    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that result in the smallest post_residual (tightest packing).
    // The base score is already post_residual, so we start with that.

    // 2. Penalty for creating "Dead Space":
    // If post_residual is small but > 0, it often prevents larger items from fitting.
    // If next_item_size exists, penalize if post_residual is just below the next item size.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 50.0 + (next_item_size - post_residual) as f64;
    }

    // 3. Harmonic/Modulo adjustment:
    // Prefer bins that leave a residual which is a multiple of common item sizes or fractions of capacity.
    // This reduces fragmentation by aligning remaining space with likely future item sizes.
    let remainder_mod = (post_residual % 20) as f64;
    score += remainder_mod * 0.5;

    // 4. Strategic new bin opening (The "New Bin" candidate):
    // If this is a new bin (bin_residual == bin_capacity), score it based on the mean residual.
    // We only open a new bin if the current mean_residual is already quite tight (high fragmentation),
    // or if fitting_bins_count is low, indicating we are running out of good options.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin is high to encourage filling existing ones.
        score = 45.0 + (mean_residual * 0.5);

        // If we have very few options, lower the barrier to open a new bin.
        if fitting_bins_count < 2 {
            score -= 10.0;
        }
    }

    // 5. Progression scaling:
    // As the stream nears completion, become more aggressive in packing to avoid opening new bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

