pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit logic).
    // Penalize large post_residual to encourage tight packing.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If post_residual perfectly matches or is slightly larger than the next item,
    // heavily reward this bin to avoid fragmentation.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let waste = (post_residual - next_item_size) as f64;
            score -= (100.0 - waste) * 2.0;
        }
    }

    // 3. Fragmentation Avoidance: If this bin is the last one that can fit the item,
    // and the resulting post_residual is very small (e.g., < 10), it is a "dead zone".
    // Heavily penalize dead zones to force use of other bins if possible.
    if fitting_bins_count == 1 && post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }

    // 4. Global Load Balancing: Avoid creating bins that deviate significantly from the mean_residual.
    // This helps keep bins packed at similar densities.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. New Bin Policy: Discourage opening a new bin unless the current empty space is tight.
    // Opening a new bin (bin_residual == bin_capacity) is penalized by default via the base score.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If we are near the end of the stream, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // 2. Harmonic Class logic: Favor residuals that are multiples of common item sizes
    // We prioritize bins that result in a post_residual that is either 0 (perfect fit)
    // or a value likely to accommodate the next item.

    if post_residual == 0 {
        score -= 500.0; // Strong reward for perfect filling
    } else {
        // Penalty for creating 'fragmented' space (e.g., 1-9) which is hard to fill
        if post_residual < 10 {
            score += 150.0;
        }

        // Lookahead heuristic: If the next item fits into the current post_residual, 
        // prioritize this bin to reduce fragmentation.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 200.0;
            // Further reward if the residual after the next item is also small
            let double_residual = post_residual - next_item_size;
            if double_residual < 5 {
                score -= 100.0;
            }
        }
    }

    // 3. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless
    // the existing open bins are poor candidates (high mean_residual).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Only open a new bin if the average residual is already quite low,
            // meaning existing bins are "crowded" and likely to cause fragmentation.
            score += 120.0 + (mean_residual * 2.0);
        }
    }

    // 4. Scarcity/Fitting logic:
    // If this is the only bin that can fit the item, we must take it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // 5. Progression scaling:
    // As we approach the end of the stream, prioritize tighter packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 50.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic penalty for creating unusable fragments (dead space < 10)
    // Small residuals are dangerous as they cannot accommodate the minimum item size (10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If next_item_size is large, favor larger post_residual
    // to avoid forcing a new bin for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // 3. Penalty for opening a new bin prematurely
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the average residual is already quite low,
        // suggesting current bins are too packed to handle future variance.
        if open_bins_count > 0 && mean_residual > 20.0 {
            score -= 10.0;
        } else {
            score += 45.0;
        }
    }

    // 4. Harmonic class bias: Favor filling bins to near-capacity (Best Fit Decreasing style)
    // Minimize the residual, but penalize tiny residuals that don't fit the next expected item.
    // We normalize the score by the progress to be more aggressive towards the end of the stream.
    let progress = step_index as f64 / total_items as f64;
    score += (post_residual as f64 / bin_capacity as f64) * (10.0 * progress);

    // 5. If this is the only bin that fits, prioritize it heavily
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}
